def standard():
    x = Symbol('x')
    h = expand((-6)*x**1+(-2)*x**2)
    pts = [Integer(-3)] + sorted(set(r for r in solve(h, x) if r.is_real and -3 < r < 0)) + [Integer(0)]
    tot = 0
    for p_, q_ in zip(pts, pts[1:]):
        tot += Abs(integrate(h, (x, p_, q_)))
    tot = tot*Rational(3, 1)
    return int(tot)

def unique():
